mapper.select:
SELECT m.id, t.article_type_name, m.sort, m.news_name, m.introduction, m.is_outside, m.link_url, m.is_show, m.create_time FROM t_portal_article_manage m LEFT JOIN t_portal_article_type t on t.id = m.article_type_id where m.is_valid = 1 and t.is_valid = 1
and m.news_name like concat('%',#{query.newsName},'%')
and m.article_type_id = #{query.articleTypeId}
and m.create_time between #{query.createTimeStart} and #{query.createTimeEnd}
and m.school_id = #{query.schoolId}
order by m.sort asc

SELECT m.id, m.news_name, m.sort, t.article_type_name, m.introduction, m.create_time, m.is_show, m.photo_url, m.is_outside, m.link_url FROM t_portal_article_manage m LEFT JOIN t_portal_article_type t ON t.id = m.article_type_id WHERE m.article_type_id = #{query.id} AND m.is_show = 1 AND m.is_valid = 1 AND t.is_valid = 1 AND t.is_enable = 1
and m.school_id = #{query.schoolId}
order by m.sort,m.create_time desc
